import { test, expect } from 'bun:test';
import { safeRedirect } from '../src/redirect.js';
test('paths on our site are kept', () => {
  expect(safeRedirect('/dashboard')).toBe('/dashboard');
  expect(safeRedirect('/orders?id=3#top')).toBe('/orders?id=3#top');
});
test('absolute urls on our site are kept', () => expect(safeRedirect('https://app.example.test/home')).toBe('https://app.example.test/home'));
test('other sites fall back to /', () => {
  expect(safeRedirect('https://other.test/x')).toBe('/');
  expect(safeRedirect('')).toBe('/');
});

