import { test, expect } from 'bun:test';
import { safeRedirect } from '../src/redirect.js';
const bad = [
  '//evil.test',
  '//evil.test/path',
  'https://app.example.test.evil.test/',
  'https://evil.test/app.example.test',
  'https://app.example.test@evil.test/',
  '/\\evil.test',
  '\\\\evil.test',
  'https:\\\\evil.test',
  '/\t/evil.test',
  'javascript:alert(1)',
  'http://app.example.test/',
];
test('anything that leaves our site falls back to /', () => {
  for (const t of bad) expect(safeRedirect(t)).toBe('/');
});
test('real paths still work', () => expect(safeRedirect('/a/b?c=d')).toBe('/a/b?c=d'));
